mapper.update:
UPDATE artifact_ledger
SET storage_type = #{newStorageType},
    storage_key = #{newStorageKey},
    storage_ref = #{newStorageRef},
    update_time = NOW()
WHERE artifact_id = #{artifactId}
  AND storage_type = #{expectedStorageType}
  AND storage_key = #{expectedStorageKey}
  AND (deleted IS NULL OR deleted = 0)

mapper.select:
SELECT * FROM artifact_ledger
WHERE trace_id = #{traceId}
  AND (deleted IS NULL OR deleted = 0)
  AND (artifact_type IS NULL OR LOWER(artifact_type) NOT IN ('llm_response', 'tool_result'))
  AND (storage_type IS NULL OR LOWER(storage_type) != 'inline_summary')
ORDER BY create_time ASC LIMIT #{limit}
